/**
 * ============================
 *  Import Set – Strict Types
 * ============================
 */

/* ----------------------------------------
   Source Script Types
----------------------------------------- */
import type { TableName } from '../db/Table'

/** Function signature for custom source field transformation */
export type ImportSetEntrySourceFn = (source: any) => string

/** Function signature for transform map script */
export type ImportSetTransformMapFn = (source: any, target: any, map: any, log: any, isUpdate: boolean) => void

/** Function signature for transform scripts */
export type ImportSetScriptFn = (source: any, map: any, log: any, target: any) => boolean | undefined

/* ----------------------------------------
   Transform Script Configuration
----------------------------------------- */

/**
 * Transform script configuration.
 * When runScript is true, a script can optionally be provided.
 */
type ScriptConfig = {
    runScript?: boolean
    script?: ImportSetTransformMapFn | string
}

/* ----------------------------------------
   Field Mapping Types
----------------------------------------- */

/**
 * Valid date format patterns for date field transformations
 */
type DateFormat =
    | 'dd-MM-yyyy'
    | 'yyyy-MM-dd'
    | 'yyyy-dd-MM'
    | 'MM-dd-yyyy HH:mm:ss z'
    | 'yyyy-MM-dd HH:mm:ss'
    | 'HH:mm:ss'
    | 'MM-dd-yyyy HH:mm:ss'
    | 'dd-MM-yyyy HH:mm:ss z'
    | 'MM-dd-yyyy'
    | 'dd-MM-yyyy HH:mm:ss'

/**
 * Base properties for field mapping configuration.
 * The targetField is omitted here since it's used as the key in the fields object.
 */
type ImportSetFieldBase = {
    sourceField?: string
    choiceAction?: 'reject' | 'ignore' | 'create'
    dateFormat?: DateFormat
    referenceValueField?: string
}

/**
 * Complete field mapping configuration.
 */
type ImportSetFieldValue = ImportSetFieldBase & {
    useSourceScript?: boolean
    sourceScript?: ImportSetEntrySourceFn | string
    coalesce?: boolean
    coalesceCaseSensitive?: boolean
    coalesceEmptyFields?: boolean
}

/* ----------------------------------------
   Transform Script Object
----------------------------------------- */

/**
 * Transform script lifecycle hooks.
 */
type ScriptTiming =
    | 'onBefore'
    | 'onAfter'
    | 'onReject'
    | 'onStart'
    | 'onForeignInsert'
    | 'onComplete'
    | 'onChoiceCreate'

/**
 * Base transform script configuration.
 */
type ImportSetScriptBase = {
    active?: boolean
    order?: number
    when?: ScriptTiming
    script?: ImportSetScriptFn | string
}

/**
 * Transform script configuration with required ID.
 */
type ImportSetScript = Now.Internal.WithID<ImportSetScriptBase>

/* ----------------------------------------
   Import Set Root Configuration
----------------------------------------- */

/**
 * Main Import Set configuration type.
 * Defines the complete structure for an import set transform map.
 */
type ImportSetType = {
    /** Display name of the import set */
    name: string

    /** Target table to insert/update records */
    targetTable: TableName

    /** Source staging table name */
    sourceTable: TableName

    /** Execution order (lower numbers run first) */
    order?: number

    /** Whether this import set is active */
    active?: boolean

    /** Run business rules on target table */
    runBusinessRules?: boolean

    /** Mandatory field enforcement level
     * - 'no': do not enforce target table mandatory fields during transform
     * - 'onlyMappedFields': enforce mandatory only for fields you map in `fields`
     * - 'allFields': enforce all target table mandatory fields; unmapped required fields must still be provided or the row will be rejected
     */
    enforceMandatoryFields?: 'no' | 'onlyMappedFields' | 'allFields'

    /** Copy empty fields from source to target */
    copyEmptyFields?: boolean

    /** Create new record if coalesce finds no match */
    createOnEmptyCoalesce?: boolean

    /**
     * Field mappings: targetField -> sourceField or configuration object.
     * - Simple string: direct field mapping
     * - Object: advanced mapping with transformations and options
     */
    fields?: { [targetField: string]: string | ImportSetFieldValue }

    /** Transform scripts for various lifecycle hooks */
    scripts?: ImportSetScript[]
} & ScriptConfig

/**
 * Import Set configuration with required system ID and metadata.
 */
type ImportSet = Now.Internal.WithID<ImportSetType & Now.Internal.Meta>

/* ----------------------------------------
   Factory Function
----------------------------------------- */

/**
 * Creates an Import Set: defines how rows in a staging/source table are transformed and loaded into a target table (`sys_transform_map`).
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **name** - display name of the import set
 *   * **targetTable** - table receiving the final records (e.g., `incident`)
 *   * **sourceTable** - staging/source table holding raw rows (e.g., `u_import_incidents`)
 *   * **order**? - execution order for multiple import sets; lower runs first
 *   * **active**? - whether the import set is enabled
 *   * **runBusinessRules**? - whether to run business rules on the target table
 *   * **enforceMandatoryFields**? - mandatory enforcement level (`'no' | 'onlyMappedFields' | 'allFields'`)
 *   * **copyEmptyFields**? - whether empty source values overwrite target values
 *   * **createOnEmptyCoalesce**? - insert a new record when no coalesce match is found
 *   * **fields**? - field mappings for loading data into the target table. Each key is a target field and the value is either:
 *       - a string: `'source_field'` for direct mapping, or
 *       - an object with:
 *         - **sourceField** - name of the source column
 *         - **coalesce**? - mark this as a match key for updates (with **coalesceCaseSensitive**? and **coalesceEmptyFields**?)
 *         - **choiceAction**? - how to handle unmapped choices (`'reject' | 'ignore' | 'create'`)
 *         - **dateFormat**? - parse dates using a specific format
 *         - **referenceValueField**? - alternate source column to resolve reference values
 *         - **useSourceScript**? - enable a per-field transform
 *         - **sourceScript**? - a function `(source) => any` or a string script executed before mapping
 *   * **scripts**? - array of transform scripts run at specific lifecycle points with:
 *       - **active**? - whether this script runs
 *       - **order**? - script execution order
 *       - **when**? - lifecycle timing (`onBefore | onAfter | onReject | onStart | onForeignInsert | onComplete | onChoiceCreate`)
 *       - **script**? - string script body
 *   * **runScript**? - whether to run a top-level map script
 *   * **script**? - string content of the top-level map script when `runScript` is `true`
 *
 * **/

export function ImportSet(config: ImportSet): ImportSet {
    return config
}
